const fs=require('fs');
const mainPath=process.argv[2],assetPath=process.argv[3];
if(!mainPath||!assetPath)throw Error('USAGE: node patch-worker-eventflow-annotation-route main.js expanded.js');
let src=fs.readFileSync(mainPath,'utf8');
const asset=fs.readFileSync(assetPath,'utf8');
const CONST_NAME='__B46_EVENTFLOW_SIGNAL_JS_20261002__';
const OLD_REV='eventflow-signal-entry-20261002';
const NEW_REV='eventflow-signal-annotation-20261004';
const NEW_MARKER='B46_EVENTFLOW_SIGNAL_ANNOTATION_20261004';
if(!asset.includes('B46_EVENTFLOW_SIGNAL_ENTRY_20261002'))throw Error('PATCHED_ASSET_BASE_MARKER_MISSING');
if(!asset.includes(NEW_MARKER))throw Error('PATCHED_ASSET_NEW_MARKER_MISSING');
if(src.includes(NEW_REV)||src.includes(NEW_MARKER))throw Error('WORKER_ALREADY_ANNOTATION_PATCHED');
const start=`const ${CONST_NAME}=`;
const finish=';\nasync function noStoreUiAsset(request, env) {';
const startCount=src.split(start).length-1,finishCount=src.split(finish).length-1;
if(startCount!==1||finishCount!==1)throw Error(`EVENTFLOW_CONST_ANCHOR_${startCount}_${finishCount}`);
const a=src.indexOf(start),b=src.indexOf(finish,a+start.length);
if(a<0||b<0||b<=a)throw Error('EVENTFLOW_CONST_RANGE_MISSING');
const beforeFetch=(src.match(/\bfetch\(/g)||[]).length;
src=src.slice(0,a)+start+JSON.stringify(asset)+src.slice(b);
const revCount=src.split(OLD_REV).length-1;
if(revCount!==1)throw Error(`REVISION_ANCHOR_COUNT_${revCount}`);
src=src.replace(OLD_REV,NEW_REV);
const afterFetch=(src.match(/\bfetch\(/g)||[]).length;
if(beforeFetch!==afterFetch)throw Error(`WORKER_FETCH_COUNT_CHANGED_${beforeFetch}_${afterFetch}`);
if((src.split(`return new Response(${CONST_NAME}`).length-1)!==1)throw Error('EVENTFLOW_ROUTE_REF_BAD');
if(!src.includes(NEW_MARKER)||!src.includes(NEW_REV))throw Error('WORKER_PATCH_VERIFY_FAILED');
fs.writeFileSync(mainPath,src);
console.log(JSON.stringify({ok:true,assetBytes:asset.length,workerBytes:src.length,beforeFetch,afterFetch,revision:NEW_REV}));
